#include <bits/stdc++.h>
using namespace std;
#define int long long
const int MOD_A=998244353;
const int MOD_B=1000000007;
int answerSum;
int totalN;
int counter;
vector<int> valuesArr[7];
int sumValuesArr[7];
void build(int level,int prefixSum){
	if(level==7) return;
	valuesArr[level].push_back((counter - prefixSum + MOD_A) % MOD_A);
	sumValuesArr[level] += (counter - prefixSum + MOD_A) % MOD_A;
	counter++;
	for(int d=0; d<=9; ++d){
		build(level+1, prefixSum*10+d);
	}
}
bool inRangeCheck(int x){
	const int half=1000000;
	return x*half+999999 <= totalN && x*half*10 > totalN;
}
int count2Local;
int powTenLocal[7]={1,10,100,1000,10000,100000,1000000};
void dfsExplore(int level,int num){
	if(num > totalN) return;
	if(inRangeCheck(num)){
		for(int i=0; i<=6; ++i){
			int offset = ((count2Local+1 - (num*powTenLocal[i])) % MOD_A + MOD_A) % MOD_A;
			int pos = lower_bound(valuesArr[i].begin(), valuesArr[i].end(), MOD_A - offset) - valuesArr[i].begin();
			answerSum += (sumValuesArr[i] + offset * (int)valuesArr[i].size() - MOD_A * ((int)valuesArr[i].size() - pos)) % MOD_B;
			answerSum %= MOD_B;
		}
		count2Local += counter;
	}
	else{
		count2Local++;
		answerSum += ((count2Local - num) % MOD_A + MOD_A) % MOD_A;
		answerSum %= MOD_B;
		for(int d=0; d<=9; ++d){
			if(level==0 && d==0) continue;
			dfsExplore(level+1, num*10+d);
		}
	}
}
int main(){
	cin >> totalN;
	build(0,0);
	for(int i=0; i<=6; ++i) sort(valuesArr[i].begin(), valuesArr[i].end());
	count2Local = -1;
	dfsExplore(0,0);
	cout << answerSum << "\n";
}
